-- Servicios de la landing de Marketing Digital con la estructura de ¿Qué
-- hacemos? (bajada, título, texto, puntos y animación del servicio): los 6
-- servicios de la agencia contados desde lo digital.
UPDATE "Landing" SET "servicesJson" = '[{"tagline": "Definimos el rumbo digital", "title": "Estrategia *digital.*", "body": "Antes de publicar o pautar, definimos a dónde querés llegar. Analizamos tu negocio, tu audiencia y tu competencia para armar un plan digital con objetivos medibles y canales priorizados.", "bullets": "Diagnóstico del punto de partida digital\nPosicionamiento de marca y estrategia de comunicación\nPlanificación de medios y análisis de performance\nInvestigación de mercado y análisis competitivo", "service": "estrategia-consultoria"}, {"tagline": "Contenido que conecta", "title": "Redes sociales y *contenido.*", "body": "Planificamos y creamos contenido con identidad propia, pensado para cada plataforma y conectado con los objetivos de la marca, para que tenga algo para decir y lo diga bien.", "bullets": "Estrategia y calendario de contenidos para redes\nStorytelling y redacción creativa\nDirección de arte, diseño y contenido visual\nInfluencer marketing y gestión de contenidos en redes", "service": "creatividad-contenido"}, {"tagline": "Optimizamos cada inversión", "title": "Publicidad digital y *performance.*", "body": "Planificamos, gestionamos y optimizamos campañas pagas con foco en resultados de negocio, y medimos cada acción para saber qué funciona y dónde conviene invertir.", "bullets": "Meta Ads, Google Ads, TikTok Ads y LinkedIn Ads\nEstrategias y planificación de medios digitales\nGestión y optimización de eCommerce\nDashboards y reporting a medida", "service": "performance-medios"}, {"tagline": "Una marca coherente en digital", "title": "Branding y *diseño.*", "body": "Construimos y adaptamos la identidad de tu marca para que se vea consistente y reconocible en cada punto de contacto digital, de las redes al sitio web.", "bullets": "Creación y rediseño de identidad visual\nNaming y conceptualización de marca\nManuales de marca y sistemas gráficos", "service": "branding-diseno"}, {"tagline": "Historias que se comparten", "title": "Producción *audiovisual.*", "body": "Producimos videos y piezas audiovisuales adaptadas a cada canal y formato digital, del concepto a la edición final.", "bullets": "Spots publicitarios para digital y redes\nProducción de contenido para marca empleadora y campañas\nCobertura de eventos, BTL y experiencias\nDirección creativa y técnica integral", "service": "produccion-audiovisual"}, {"tagline": "Donde la data se convierte en ventas", "title": "CRM y *automatización.*", "body": "Conectamos el marketing con las ventas: implementamos herramientas que integran datos, automatizan la comunicación y mejoran la toma de decisiones.", "bullets": "CRM, email marketing y flujos automatizados\nIntegración con Data4Sales, Flexi y otras plataformas\nConfiguración y monitoreo de performance omnicanal\nVisualización de datos e inteligencia comercial", "service": "tecnologia-automatizacion"}]' WHERE "slug" = 'marketing-digital';
